export function initialise(ctx) {
  ctx.store.t = 0;
}

export function render(ctx) {
  ctx.store.t += ctx.deltaTime * (ctx.params.speed ?? 1);
  const { canvas, width, height, store } = ctx;
  canvas.fillStyle = '#1a1a1a';
  canvas.fillRect(0, 0, width, height);
  canvas.fillStyle = '#fff';
  canvas.beginPath();
  const r = Math.min(width, height) * 0.18;
  const cx = width / 2 + Math.cos(store.t) * width * 0.25;
  const cy = height / 2 + Math.sin(store.t * 0.7) * height * 0.25;
  canvas.arc(cx, cy, r, 0, Math.PI * 2);
  canvas.fill();
}
